def balance_point(changes):
    total = sum(changes)
    left = 0
    for i, value in enumerate(changes):
        if left == total - left - value:
            return i
        left += value
    return -1

def merge_bookings(bookings):
    merged = []
    for start, end in sorted(bookings):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

def affordable_route(costs, budget):
    left = total = best = 0
    for right, cost in enumerate(costs):
        total += cost
        while total > budget and left <= right:
            total -= costs[left]
            left += 1
        best = max(best, right - left + 1)
    return best

