def mirror_insertions(text):
    n = len(text)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for size in range(2, n + 1):
        for left in range(n - size + 1):
            right = left + size - 1
            if text[left] == text[right]:
                dp[left][right] = dp[left + 1][right - 1] if size > 2 else 0
            else:
                dp[left][right] = 1 + min(dp[left + 1][right], dp[left][right - 1])
    return dp[0][n - 1]

