def parcel_capacity(weights, days):
    if not weights:
        return 0
    low, high = max(weights), sum(weights)
    while low < high:
        capacity = (low + high) // 2
        used, load = 1, 0
        for weight in weights:
            if load + weight > capacity:
                used += 1
                load = 0
            load += weight
        if used <= days:
            high = capacity
        else:
            low = capacity + 1
    return low

