def emergency_path(grid):
    from collections import deque
    rows, cols = len(grid), len(grid[0])
    queue = deque([(0, 0, 0, 0)])
    seen = {(0, 0, 0)}
    while queue:
        r, c, used, distance = queue.popleft()
        if (r, c) == (rows - 1, cols - 1):
            return distance
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                next_used = used + (grid[nr][nc] == '#')
                state = (nr, nc, next_used)
                if next_used <= 1 and state not in seen:
                    seen.add(state)
                    queue.append((nr, nc, next_used, distance + 1))
    return -1

def coupon_route(n, roads):
    import heapq
    graph = [[] for _ in range(n)]
    for a, b, cost in roads:
        graph[a].append((b, cost))
    distance = {(0, 0, 0): 0}
    heap = [(0, 0, 0, 0)]
    while heap:
        price, node, used, previous = heapq.heappop(heap)
        if price != distance.get((node, used, previous)):
            continue
        if node == n - 1:
            return price
        for child, cost in graph[node]:
            options = [(price + cost, used, 0)]
            if used < 2 and not previous:
                options.append((price + cost // 2, used + 1, 1))
            for candidate, next_used, last in options:
                state = (child, next_used, last)
                if candidate < distance.get(state, float('inf')):
                    distance[state] = candidate
                    heapq.heappush(heap, (candidate, child, next_used, last))
    return -1

