def minimum_tokens(values, target):
    unreachable = target + 1
    dp = [0] + [unreachable] * target
    for total in range(1, target + 1):
        for value in set(values):
            if value <= total:
                dp[total] = min(dp[total], dp[total - value] + 1)
    return dp[target] if dp[target] <= target else -1

def workshop_order(start, transition):
    n = len(start)
    if n == 0:
        return 0
    dp = [[float('inf')] * n for _ in range(1 << n)]
    for job in range(n):
        dp[1 << job][job] = start[job]
    for mask in range(1 << n):
        for last in range(n):
            if not (mask >> last & 1):
                continue
            for job in range(n):
                if not (mask >> job & 1):
                    nxt = mask | (1 << job)
                    dp[nxt][job] = min(dp[nxt][job], dp[mask][last] + transition[last][job])
    return min(dp[-1])

def fusion_cost(weights):
    n = len(weights)
    if n < 2:
        return 0
    prefix = [0]
    for weight in weights:
        prefix.append(prefix[-1] + weight)
    dp = [[0] * n for _ in range(n)]
    for size in range(2, n + 1):
        for left in range(n - size + 1):
            right = left + size - 1
            interval_sum = prefix[right + 1] - prefix[left]
            dp[left][right] = min(dp[left][split] + dp[split + 1][right] + interval_sum for split in range(left, right))
    return dp[0][-1]
